const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const figures={figure1:['Figure 1 · Cohort and temporal landscape','Cohort construction, timing of first coded PO-AKI, and perioperative EHR event density. Source: main manuscript, Figure 1.'],figure2:['Figure 2 · STREAM architecture','Original manuscript schematic. The Methods define the index as recorded surgery completion; the pre-index segment can contain intraoperative records.'],figure3:['Figure 3 · Discrimination over time','Mean AUPRC across five fold-specific models. Bands are fold-wise minimum–maximum, not confidence intervals. The secondary axis shows coded PO-AKI prevalence in the remaining risk set.'],figure4:['Figure 4 · Calibration across time','Calibration at surgery completion, 6, 12, 24, 48 hours and day 7. The diagonal indicates perfect calibration. Quantitative results appear in Supplementary Table S6.'],figure5:['Figure 5 · Event-arrival attribution','Code-level mean changes in model logit during the first 7 postoperative days. Error bars show the five-model minimum–maximum range. These are model associations, not causal effects.'],figure6:['Figure 6 · Within-window order sensitivity','Panel A: random order perturbations across 6-hour windows. Panel B: the complete 0–6 h window for an illustrative episode with coded PO-AKI at 5.8 h. The same 46 events occupy the same timestamp positions, with event identities assigned in reverse order.'],s1:['Supplementary Figure S1 · Grouped deletion','Events with the same modality and code are grouped within perioperative periods, removed, and rescored. Attribution is the original minus perturbed model logit.'],s2:['Supplementary Figure S2 · Complementary attribution','Age substitution uses 48 years as reference. Surgery substitution covers 75 types (Spearman ρ = 0.667 with observed incidence). Temporal grouped deletion characterizes period-specific model reliance.'],s3:['Supplementary Figure S3 · Event-arrival case studies','Two illustrative episodes. Red/blue indicate increases/decreases in estimated risk; darker shades identify threshold-crossing updates. Contributions are computed on the logit scale; the plotted trajectory is on the probability scale.'],s4:['Supplementary Figure S4 · Fixed-window case studies','Time-series Transformer predictions for the same two episodes, updated at predefined 6-hour intervals. The 0.50 line is a visualization reference, not a clinically validated alert threshold.']};
const fig=(id,cls='')=>`<button class="fig ${cls}" data-figure="${id}" aria-label="Enlarge ${figures[id][0]}"><span class="expand">Expand ↗</span><img src="assets/${id}.png" alt="${figures[id][0]}" loading="lazy"><span class="figcap">${figures[id][0]} · Click to inspect the original</span></button>`;
const head=(tag,title,desc='')=>`<div class="slide-head"><span class="eyebrow">${tag}</span><h2>${title}</h2>${desc?`<p class="lede">${desc}</p>`:''}</div>`;
const source=(text,id='')=>`<div class="source"><span>${text}</span>${id?`<button data-figure="${id}">View source figure ↗</button>`:''}</div>`;
const slides=[
{id:'opening',title:'Event by event',tag:'Overview',notes:"Open by framing this study as a question about how longitudinal EHR data are represented. Surgery completion provides a clear temporal anchor. Clinical information then arrives irregularly, and STREAM updates the risk of coded PO-AKI as each event enters the stream.\nThe three headline numbers describe the analytic cohort, surgery-index AUPRC, and postoperative macro-AUPRC across 6-hour intervals. The two AUPRC values evaluate different prediction stages and should not be compared directly as better or worse performance.\nThe latest main manuscript and supplementary material are the source of the presentation. Use the figure controls or the final Evidence library chapter to inspect original figures and complete tables.",html:`<div class="hero"><div><span class="eyebrow">LONGITUDINAL EHR · DYNAMIC CLINICAL PREDICTION</span><h1>STREAM</h1><p class="subtitle manuscript-title">Sequential Transformer for Risk Estimation from Asynchronous Medical Events for Dynamic Postoperative AKI Prediction</p><div class="actions"><button class="primary" data-go="1">Explore the study →</button><button data-go="7">Jump to results</button></div><p class="byline">Shuyu Lu<br>UTHealth Houston · The University of Texas at Austin</p></div><div class="heroart"><span class="eyebrow">FROM CLINICAL EVENTS TO EVOLVING ESTIMATES</span><svg viewBox="0 0 520 230" role="img" aria-label="Conceptual sequence of irregular events with a surgery anchor and subsequent model updates"><path d="M10 70H510" stroke="#547b7c"/><path d="M200 25V210" stroke="#93b7a9" stroke-dasharray="4 6"/><g fill="#bbd6b8"><circle cx="30" cy="70" r="9"/><circle cx="90" cy="70" r="9"/><circle cx="115" cy="70" r="9"/></g><rect x="177" y="47" width="46" height="46" rx="8" fill="#d4aa5f"/><text x="200" y="120" text-anchor="middle" fill="#e5cd9d" font-size="12">SURGERY END</text><g fill="#79c2a9"><circle cx="265" cy="70" r="9"/><circle cx="290" cy="70" r="9"/><circle cx="365" cy="70" r="9"/><circle cx="390" cy="70" r="9"/><circle cx="475" cy="70" r="9"/></g><path d="M200 180H265V158H290V166H365V135H390V146H475V124H510" fill="none" stroke="#b4e9cf" stroke-width="3"/><g fill="#b4e9cf"><circle cx="200" cy="180" r="4"/><circle cx="265" cy="158" r="4"/><circle cx="290" cy="166" r="4"/><circle cx="365" cy="135" r="4"/><circle cx="390" cy="146" r="4"/><circle cx="475" cy="124" r="4"/></g><text x="10" y="210" fill="#adc4c7" font-size="11">Historical context</text><text x="315" y="210" fill="#adc4c7" font-size="11">Event-by-event updates →</text></svg><div class="hero-facts"><div><b>167,078</b><span>surgical episodes</span></div><div><b>0.771</b><span>surgery-index AUPRC</span></div><div><b>0.589</b><span>dynamic macro-AUPRC</span></div></div><p class="art-note" style="margin-top:20px">Conceptual illustration above · Reported study results below</p></div></div><div class="affiliation-logos" aria-label="Research team and institutions"><img class="logo-team" src="assets/logo-team-ai.png" alt="TEAM-AI: Translational AI Excellence and Applications in Medicine"><img class="logo-uthealth" src="assets/logo-uthealth-houston.png" alt="UTHealth Houston"><img class="logo-dell" src="assets/logo-dell-medical-school.png" alt="The University of Texas at Austin, Dell Medical School"></div>${source('Retrospective study · 30-day coded PO-AKI · Main manuscript, Abstract and Table 2')}`},
{id:'question',title:'Why event streams?',tag:'The question',notes:"Distinguish the three ways of organizing information. Static models provide one estimate at surgery completion. Fixed-window models group records into 6-hour intervals. Event streams preserve individual records and their order.\nThe schematic illustrates representations; it is not simulated patient data. Performance comparisons evaluate predictive ability, whereas permutation experiments evaluate sensitivity to ordering. Order sensitivity alone does not establish that preserving order improves accuracy.",html:head('01 / THE QUESTION','What can be learned between fixed time steps?','Clinical records arrive irregularly. Their timing, repetition and order may carry information that a fixed-window summary does not preserve.')+`<div class="triple"><article class="representation"><span class="number">01 · STATIC</span><h3>One summary</h3><p>Logistic regression and XGBoost estimate risk at the surgery index.</p><svg viewBox="0 0 310 130" aria-hidden="true"><path d="M10 45H295" stroke="#c1cbc3"/><g fill="#bac8bf"><circle cx="25" cy="45" r="5"/><circle cx="60" cy="45" r="5"/><circle cx="83" cy="45" r="5"/><circle cx="165" cy="45" r="5"/></g><rect x="202" y="20" width="70" height="50" rx="4" fill="#dae3d6"/><text x="237" y="50" text-anchor="middle" fill="#142f38" font-size="13">Summary</text><path d="M237 73V100" stroke="#82948a"/><circle cx="237" cy="109" r="7" fill="#14786e"/></svg></article><article class="representation"><span class="number">02 · FIXED WINDOWS</span><h3>One vector per interval</h3><p>LSTM, GRU-D and a Transformer process regular 6-hour positions.</p><svg viewBox="0 0 310 130" aria-hidden="true"><g fill="#e2e8dc" stroke="#bcc9be"><rect x="10" y="28" width="65" height="60"/><rect x="85" y="28" width="65" height="60"/><rect x="160" y="28" width="65" height="60"/><rect x="235" y="28" width="65" height="60"/></g><g fill="#617276" font-size="12" text-anchor="middle"><text x="42" y="112">0–6 h</text><text x="117" y="112">6–12 h</text><text x="192" y="112">12–18 h</text><text x="267" y="112">18–24 h</text></g><path d="M42 58H267" stroke="#82948a" stroke-dasharray="4 5"/></svg></article><article class="representation featured"><span class="number">03 · EVENT STREAM</span><h3>Each recorded event</h3><p>STREAM updates the model estimate whenever a new event enters the sequence.</p><svg viewBox="0 0 310 130" aria-hidden="true"><path d="M10 45H300" stroke="#8ab4a5"/><g fill="#14786e"><circle cx="20" cy="45" r="7"/><circle cx="55" cy="45" r="7"/><circle cx="70" cy="45" r="7"/><circle cx="160" cy="45" r="7"/><circle cx="225" cy="45" r="7"/><circle cx="243" cy="45" r="7"/><circle cx="286" cy="45" r="7"/></g><path d="M20 105H55V88H70V99H160V78H225V88H243V65H286V73H300" fill="none" stroke="#14786e" stroke-width="2"/></svg></article></div><div class="note-box" style="margin-top:25px">Study question: how does retaining individual clinical events support dynamic prediction, and how does their within-window order affect STREAM’s estimates?</div>${source('Main manuscript · Introduction and Discussion. Prior work includes STraTS, Event Stream GPT, Curiosity, BEHRT and Med-BERT.')}`},
{id:'cohort',title:'The study cohort',tag:'Cohort',notes:"The data come from Memorial Hermann Health System, with Cerner EHR records converted to OMOP CDM 5.4. The analytic unit is a surgical episode: an eligible noncardiac surgery with its associated perioperative event stream. A patient may contribute multiple surgeries to the development set.\nThe development and test sets contain 143,540 and 23,538 episodes, with coded PO-AKI proportions of 5.7% and 10.1%, respectively. The final counts differ from the initial 80:20 chronological split. Cross-validation folds are grouped by patient, and no patient appears in both development and testing.\nThe study start date is 1 January 2014 throughout. Development covers 1 January 2014 through 29 August 2022; testing covers 30 August 2022 through 13 April 2024.",html:head('02 / COHORT','167,078 surgical episodes. One clinical anchor.','A retrospective, single-health-system cohort of adult noncardiac surgery, linked to longitudinal OMOP CDM records.')+`<div class="statrow"><div class="stat"><b>134,741</b><span>distinct patients</span></div><div class="stat"><b>10,518</b><span>episodes with coded PO-AKI</span></div><div class="stat"><b>6</b><span>noncardiac surgical categories</span></div></div><div class="split"><div><div class="timeline"><div><span class="eyebrow">DEVELOPMENT · 1 JAN 2014–29 AUG 2022</span><h3>143,540 episodes</h3><p>8,147 with coded PO-AKI <b>(5.7%)</b></p><p class="small" style="margin-top:12px">Five patient-grouped folds</p></div><div class="test"><span class="eyebrow">TEMPORAL TEST · 30 AUG 2022–13 APR 2024</span><h3>23,538 episodes</h3><p>2,371 with coded PO-AKI <b>(10.1%)</b></p><p class="small" style="margin-top:12px">One qualifying surgery per test patient</p></div></div><div class="note-box">Development and test sets contain no shared patients. All five fold-specific models are evaluated on the same held-out test set.</div></div><div class="stack"><h3>From source procedures to eligible surgery</h3><p class="small">768,613 records → 602,871 records in the 200 most frequent procedure types → 167,078 eligible episodes.</p><details><summary>View sequential exclusion counts</summary><div class="risk-table"><div>Noninvasive procedures <b>379,195</b></div><div>Cardiac surgery <b>4,995</b></div><div>Age &lt;18 years <b>10,934</b></div><div>AKI recorded in preceding year <b>6,435</b></div><div>Unknown sex <b>34,234</b></div></div></details><div class="tagrow"><span>Abdominal</span><span>Intracranial</span><span>Thoracic</span><span>Spinal</span><span>Joint</span><span>Skin</span></div></div></div>${source('Main manuscript · Study Cohort Construction and Table 1','figure1')}`},
{id:'landscape',title:'The perioperative landscape',tag:'Clinical context',notes:"Explain why the perioperative setting is useful for studying dynamic prediction: it combines a clear anchor with many asynchronously recorded events around surgery. Figure 1 shows that event density and coded diagnoses are concentrated early after surgery.\nThe outcome is 30-day coded PO-AKI, defined by the first postoperative record of ICD-9-CM 584* or ICD-10-CM N17*. This is not equivalent to physiologic KDIGO-defined AKI. Event streams are truncated at the first coded diagnosis to prevent subsequent information from entering the prediction input.\nRecorded timestamps do not necessarily identify the true onset of disease.",html:head('03 / CLINICAL CONTEXT','The information stream is densest near surgery.','Recorded PO-AKI diagnoses and clinical activity concentrate early, then become progressively sparser.')+`<div class="split wide">${fig('figure1')}<div class="stack"><div><span class="number">OBSERVATION WINDOW</span><h3>−7 days → surgery end → +30 days</h3></div><div><span class="number">OUTCOME</span><h3>30-day coded PO-AKI</h3><p class="small" style="margin-top:10px">First postoperative ICD-9-CM 584* or ICD-10-CM N17* diagnosis. Positive event streams are truncated at the coded endpoint.</p></div><div class="note-box">A recorded diagnosis marks documentation of AKI. It does not establish the physiologic onset time.</div></div></div>${source('Main manuscript · Figure 1; Outcome Definition; Event Stream Construction')}`},
{id:'representation',title:'Anatomy of an event',tag:'Representation',notes:"Each event contains a clinical code, modality, relative time, optional numerical value, value-observation indicator, and medication boundary type. Numerical values are used only for age and laboratory events.\nSelect different tokens to explain their representations. The surgery token is placed at recorded surgery completion, immediately followed by a learnable [BASE] token. Intraoperative records are not modeled as a separate segment and may be included in the pre-index segment.\nCondition codes are mapped to CCS categories. Medications are mapped to RxNorm ingredients, with the retained set covering the top 90% of frequency. Twenty-one laboratory types are represented separately, and procedures use SNOMED CT.",html:head('04 / REPRESENTATION','One sequence. Heterogeneous clinical information.','Event identity is combined with modality, timing, numerical values and medication boundaries.')+`<div class="tokens" role="group" aria-label="Explore event types"><button class="token" data-token="demo" aria-pressed="true">AGE · SEX · RACE</button><button class="token" data-token="cond" aria-pressed="false">CCS</button><button class="token med" data-token="med" aria-pressed="false">RxCUI</button><button class="token lab" data-token="lab" aria-pressed="false">LAB</button><button class="token" data-token="surgery" aria-pressed="false">SURGERY</button><button class="token base" data-token="base" aria-pressed="false">[BASE]</button><button class="token post" data-token="post" aria-pressed="false">eₛ₊₁ … eₙ →</button></div><div class="split"><div class="stack"><div class="formula">eᵢ = (cᵢ, mᵢ, tᵢ, vᵢ, oᵢ, bᵢ)<small>code · modality · relative time · numerical value · observation indicator · medication boundary</small></div><div class="formula">xᵢ = E꜀(cᵢ) + Eₘ(mᵢ) + Eᵦ(bᵢ)<br> + fₜ(tᵢ) + fᵥ(cᵢ, vᵢ, oᵢ)<small>Embeddings and continuous-feature projections are learned jointly.</small></div></div><div><div id="tokenDetail" class="note-box"></div><div class="arch-config"><div><b>128</b>hidden dimensions</div><div><b>2</b>Transformer layers</div><div><b>4</b>attention heads</div></div><div class="actions"><button data-figure="figure2">View architecture ↗</button></div></div></div>${source('Main manuscript · Model Architecture; Supplementary Tables S1–S2')}`},
{id:'attention',title:'Which events can be seen?',tag:'Architecture',notes:"Select a matrix row to show which information that position can access. This is a schematic of the attention-mask rules, not a visualization of learned attention weights.\nPre-index records and the surgery token attend bidirectionally within their segment. [BASE] attends to all pre-index positions and itself. Postoperative positions attend only to [BASE] and postoperative positions up to and including the current event. Historical context therefore reaches postoperative predictions through [BASE].\nEmphasize that the dedicated [BASE] state supports both surgery-index estimation and dynamic prediction. Its contribution is also supported by the ablation results.",html:head('05 / ARCHITECTURE','A surgery-index summary connects history to follow-up.','Select a query row to explore the structured attention mask. This is an architectural schematic, not learned attention weights.')+`<div class="matrix-layout"><div><div class="mini-label" style="margin-bottom:12px">QUERY ROW ↓ · AVAILABLE KEY POSITIONS →</div><div id="attentionMatrix" class="matrix"></div><div class="legend"><span><i></i>Visible to selected query</span><span><i style="background:#e2e5df"></i>Masked</span><span><i style="background:#d8b469"></i>[BASE] self-attention</span></div></div><div class="stack"><div id="attentionExplanation"></div><div class="note-box">The anchor is recorded surgery completion. The pre-index segment can include intraoperative records; no separate intraoperative segment was modeled.</div><button data-figure="figure2">Inspect the original architecture figure ↗</button></div></div>${source('Main manuscript · Structured block attention mask; Figure 2')}`},
{id:'training',title:'Training and fair comparison',tag:'Study design',notes:"Supplementary Table S2 specifies loss weights of 1.0 for postoperative prediction, 0.3 for surgery-index prediction, and 0.01 for MEM. MEM masks 15% of eligible pre-index codes. Checkpoints are selected using 0.9 times dynamic macro-AUPRC plus 0.1 times surgery-index AUPRC.\nStatic comparators are logistic regression and XGBoost. Sequence comparators are LSTM, GRU-D, and the Time-series Transformer. The fixed-window input has 149 positions: 28 pre-index, one baseline, and 120 postoperative positions, each with 548 features.\nAll models predict the same 30-day coded outcome. Dynamic evaluation uses a common 6-hour grid. STREAM contributes its most recent available prediction, carried forward when no new event arrives. The [BASE] prediction is carried forward until the first postoperative event.\nThe risk set comprises episodes still free of coded PO-AKI and eligible for prediction at that time. Positive episodes subsequently receive a qualifying diagnosis by postoperative day 30. Macro-averaging weights valid intervals equally rather than pooling all predictions.",html:head('06 / STUDY DESIGN','A common target. A common evaluation clock.','Models share the held-out cohort and 30-day coded outcome. Dynamic predictions are compared on the same 6-hour grid.')+`<div class="split"><div class="losses"><div class="loss"><b>1.0</b><div><h3>Postoperative online loss</h3><p>Binary cross-entropy at valid postoperative event positions.</p></div></div><div class="loss"><b>0.3</b><div><h3>Surgery-index loss</h3><p>Explicit supervision for the [BASE] risk estimate.</p></div></div><div class="loss"><b>0.01</b><div><h3>Masked event modeling</h3><p>Reconstruct 15% of eligible masked pre-index event codes.</p></div></div><p class="small">AdamW · learning rate 10⁻⁴ · batch size 16 · dropout 0.2</p></div><div class="stack"><div class="formula">149 positions × 548 features<small>Fixed-window baselines: 28 pre-index + 1 baseline + 120 postoperative positions. LSTM / GRU-D / Time-series Transformer.</small></div><div class="note-box"><b>At each evaluation time:</b> retain episodes still free of coded PO-AKI; label positive if a qualifying diagnosis occurs later by postoperative day 30.</div><p class="small">Interval-specific AUPRC → unweighted mean across valid intervals. STREAM uses the most recent available event prediction at each grid point.</p><button data-table="Algorithm 1">Open unified baseline pseudocode ↗</button></div></div>${source('Main manuscript · Training and Evaluation; Supplementary Algorithm 1 and Table S2')}`},
{id:'performance',title:'Predictive performance',tag:'Results',notes:"Table 2 reports percentages; this view converts them to a 0–1 scale. Switch among surgery-index AUPRC, dynamic macro-AUPRC, and the corresponding AUROC measures.\nSTREAM has surgery-index AUPRC of 0.7714 versus 0.7288 for the Time-series Transformer, a difference of 4.26 percentage points. Dynamic macro-AUPRC is 0.5886 versus 0.5470 for GRU-D, a difference of 4.16 percentage points. Two macro-AUROC values round to 0.948, but the original values are 0.9482 and 0.9476; do not describe them as identical.\nValues are means across five fold-specific models evaluated on the same test set. Ranges are model-wise minima and maxima, not confidence intervals or significance tests.",html:head('07 / PRIMARY RESULTS','STREAM leads both prediction stages.','Explore the means across five fold-specific models from Table 2. Static models are evaluated only at the surgery index.')+`<div class="selectrow" id="metricTabs"><button data-metric="basepr" class="active">Surgery-index AUPRC</button><button data-metric="dynpr">Dynamic macro-AUPRC</button><button data-metric="baseroc">Surgery-index AUROC</button><button data-metric="dynroc">Dynamic macro-AUROC</button></div><div class="split wide"><div><div id="performanceBars"></div><div class="chart-axis"><span>0</span><span>0.25</span><span>0.50</span><span>0.75</span><span>1.00</span></div><p class="small" style="margin-top:25px">Held-out temporal test set · n = 23,538<br>Numbers are proportions; manuscript tables report percentages.</p></div><div id="metricSummary" class="metric-summary"></div></div><div class="actions"><button data-table="Table 2.">Full table and fold ranges ↗</button><button data-table="Supplementary Table S4">All classification metrics ↗</button></div>${source('Main manuscript · Table 2; Supplementary Tables S4–S5')}`},
{id:'temporal',title:'Performance across time',tag:'Results',notes:"Use the original Figure 3 rather than fitting or inventing time-point values from the image. During the first 48 hours, STREAM AUPRC is approximately 0.75–0.79, compared with approximately 0.72–0.75 for the Time-series Transformer.\nLater follow-up has fewer positive episodes and fewer newly recorded EHR events. AUPRC declines and becomes more variable. Because risk-set composition and outcome prevalence change over time, the decline should not be interpreted directly as deterioration of the model.\nShaded bands represent fold-wise minimum–maximum ranges. A separate gray region identifies later intervals with fewer than 100 positive episodes.",html:head('08 / PERFORMANCE OVER TIME','The clearest separation occurs early after surgery.','Discrimination is evaluated repeatedly in a changing population of episodes still free of coded PO-AKI.')+`${fig('figure3')}<div class="triple" style="margin-top:25px"><div><span class="number">FIRST 48 HOURS</span><h3>≈0.75–0.79 AUPRC</h3><p class="small" style="margin-top:10px">STREAM maintains the highest reported AUPRC during the event-dense early period.</p></div><div><span class="number">LATER FOLLOW-UP</span><h3>Fewer future positives</h3><p class="small" style="margin-top:10px">Differences become less consistent as observations and remaining positive episodes become sparse.</p></div><div><span class="number">READING THE FIGURE</span><h3>Changing risk sets</h3><p class="small" style="margin-top:10px">The dashed secondary-axis curve shows coded PO-AKI prevalence in the remaining risk set.</p></div></div>${source('Main manuscript · Figure 3 and Predictive Performance Results')}`},
{id:'calibration',title:'Calibration across time',tag:'Calibration',notes:"Calibration asks whether predicted probabilities correspond to observed outcome frequencies. A lower Brier score does not establish improvement in every aspect of calibration. STREAM has the lowest Brier score at 0, 6, 12, 24, and 48 hours and at 7 days, but calibration slopes of approximately 0.65–0.72 remain below the ideal value of 1.\nSelect time points to inspect Supplementary Table S6. Brier skill scores use a prevalence-only predictor at the corresponding time as the reference. Declining prevalence means that a lower Brier score later in follow-up does not, by itself, demonstrate better calibration.\nTable S6 reports 2,368 future-positive episodes at baseline, whereas the cohort table reports 2,371. The presentation preserves each table's reported values; the time-zero boundary requires clarification.",html:head('09 / CALIBRATION','Risk probabilities carry information beyond ranking.','STREAM has the lowest reported Brier score at each evaluated time point, while calibration remains imperfect.')+`<div class="selectrow" id="calTabs">${['0 h','6 h','12 h','24 h','48 h','7 d'].map((x,i)=>`<button data-cal="${i}" class="${i===1?'active':''}">${x}</button>`).join('')}</div><div id="brierGrid" class="brier-grid"></div><div class="split" style="margin-top:28px"><div id="calDetail" class="stack"></div><div class="note-box"><b>Ideal calibration:</b> intercept 0, slope 1.<br>STREAM’s reported slopes are 0.65–0.72 across these time points. External validation and recalibration remain necessary before clinical use.</div></div><div class="actions"><button data-figure="figure4">Explore calibration curves ↗</button><button data-table="Supplementary Table S6">Complete calibration metrics ↗</button></div>${source('Supplementary Table S6 · Five-fold means; lower Brier score is better')}`},
{id:'ablation',title:'What matters to the model?',tag:'Ablation',notes:"Separate architecture, objective, and input-modality ablations. Switch between surgery-index and dynamic results to compare the effect of the same variant across prediction stages.\nRemoving medication events produces the largest dynamic decline, from 0.5886 to 0.2310. Removing condition events also has a substantial effect. Replacing the dedicated [BASE] state with the surgery token produces the largest architecture-level dynamic decrease, 2.91 percentage points.\nRemoving continuous time encoding slightly increases dynamic performance, so do not claim that every component necessarily improves performance. Without the surgery-index loss, the baseline head is not trained for that objective; its very low AUPRC is not a conventional competitive baseline result.\nReported paired differences may differ by 0.01 percentage points from subtraction of rounded table means because the original differences use unrounded values.",html:head('10 / ABLATION','Medication context and a dedicated baseline state matter.','Single-component ablations reveal different dependencies at surgery completion and during postoperative updating.')+`<div class="selectrow"><button class="active" data-ablation="dynamic">Dynamic macro-AUPRC</button><button data-ablation="baseline">Surgery-index AUPRC</button></div><div class="split wide"><div><div class="ablation-head"><span>VARIANT</span><span>AUPRC · CHANGE IN PERCENTAGE POINTS</span></div><div id="ablationBars"></div></div><div class="stack"><div class="note-box"><b>Largest input effect:</b> removing medication events reduces dynamic macro-AUPRC from 0.589 to 0.231.</div><div class="note-box"><b>Largest architecture effect:</b> replacing [BASE] with the surgery token reduces dynamic macro-AUPRC to 0.560.</div><p class="small">Removing time encoding did not reduce dynamic macro-AUPRC in this evaluation. The no-baseline-loss variant left the surgery-index head untrained.</p></div></div>${source('Main manuscript · Table 3; Supplementary Tables S7–S8')}`},
{id:'attribution',title:'Interpret individual arrivals',tag:'Interpretability',notes:"Event-arrival attribution is the logit difference between successive online states. The first postoperative event uses the [BASE] prediction as its preceding state. Positive values indicate increased model-estimated risk; negative values indicate decreased risk.\nClinical interpretation 1: arrivals of other kidney and ureter disease, diabetes with complications, and hypertension with complications increase estimated risk. These directions are consistent with renal, metabolic, and vascular vulnerability. The ADQI/POQI consensus identifies impaired kidney function, diabetes, and hypertension as PO-AKI risk factors; the attribution directions themselves come from Figure 5 of this study.\nClinical interpretation 2: records of hemorrhage during pregnancy, tranexamic acid, midazolam, and ropivacaine may identify bleeding, anesthesia, and perioperative care contexts. Medication attribution can reflect indications, procedure types, and concurrent illness; it does not establish that a medication causes kidney injury.\nClinical interpretation 3: endometriosis, ovarian cysts, and reproductive-management codes more often correspond to decreased estimated risk. These patterns may reflect particular patient groups and care pathways in this cohort. A negative update is relative to the preceding prediction and is not evidence of biological protection. Hemorrhage during pregnancy appears among positive updates, so obstetric and gynecologic records should not all be characterized as low risk.\nFor tied timestamps, marginal logit contributions are averaged over up to 20 within-timestamp permutations. The analysis covers the first 7 postoperative days, requires at least 50 contributing patients in at least one fold, and retains codes with concordant direction across all five models.",html:head('11 / EVENT-ARRIVAL ATTRIBUTION','Which newly recorded information changes the estimate?','Clinical patterns help interpret how newly recorded events change STREAM’s estimate. Select a theme to explore the results.')+`<div class="attribution-layout"><div>${fig('figure5')}<p class="small attribution-key"><b>Positive Δlogit:</b> increased model-estimated risk. <b>Negative Δlogit:</b> decreased model-estimated risk.</p></div><aside class="clinical-panel"><span class="eyebrow">CLINICAL READING OF FIGURE 5</span><div class="selectrow clinical-tabs" aria-label="Clinical interpretation themes"><button class="active" aria-pressed="true" data-clinical="vulnerability">Comorbidities</button><button aria-pressed="false" data-clinical="care">Perioperative care</button><button aria-pressed="false" data-clinical="casemix">Patient groups</button></div><div id="clinicalInterpretation" aria-live="polite"></div><details class="attribution-method"><summary>How attribution was calculated</summary><div class="formula">Δzᵢ = zᵢ − zᵢ₋₁<small>The first postoperative event is compared with [BASE]. Tied-timestamp contributions are averaged across sampled event orders.</small></div></details><p class="small clinical-scope">Clinical interpretations describe learned associations; they do not estimate causal effects.</p></aside></div>${source('Main manuscript · Figure 5 and Event-Arrival Attribution Methods · First 7 postoperative days; concordant direction across five models')}`},
{id:'cases',title:'Follow individual trajectories',tag:'Case studies',notes:"These two cases illustrate model behavior rather than population-level evidence. Select a patient, then switch between STREAM and the Time-series Transformer to compare their updating patterns for the same patient.\nSelect a landmark to highlight the corresponding column in the original figure, or use the previous and next controls for a step-by-step explanation. All curves and bars come from the original figure; no patient values were estimated or interpolated.\nThe laparoscopic appendectomy case has a first coded AKI diagnosis at 15.4 hours. The exploratory laparotomy case has no coded AKI within 30 days. Red and blue indicate increased and decreased model-estimated risk; darker colors identify updates that cross the 0.50 threshold. Each event's bar shows the predicted probability after that event is incorporated. The overall trajectory at a timestamp reflects the updated logit transformed to a probability using the sigmoid function.",html:head('12 / PATIENT-LEVEL EXAMPLES','Follow the patient, one update at a time.','Choose an episode and model, then select a landmark to highlight it in the original trajectory.')+`<div class="case-toolbar"><div class="selectrow" aria-label="Select patient"><button class="active" aria-pressed="true" data-patient="positive">PO-AKI-positive · Appendectomy</button><button aria-pressed="false" data-patient="negative">PO-AKI-negative · Laparotomy</button></div><div class="selectrow" aria-label="Select model"><button class="active" aria-pressed="true" data-case="s3">STREAM</button><button aria-pressed="false" data-case="s4">Time-series Transformer</button></div></div><div class="patient-layout"><div><div id="patientFigure" class="patient-figure"></div><div id="caseLandmarks" class="landmark-buttons" aria-label="Select trajectory landmark"></div><div class="landmark-controls"><button id="casePrev" aria-label="Previous landmark">← Previous</button><span id="casePosition"></span><button id="caseNext" aria-label="Next landmark">Next →</button></div></div><aside class="patient-insight"><span class="eyebrow" id="patientBadge"></span><h3 id="patientTitle"></h3><p id="patientOutcome" class="small"></p><div id="landmarkInfo" aria-live="polite"></div><p id="patientLegend" class="small"></p><button id="caseOriginal">Open complete source figure ↗</button></aside></div>${source('Supplementary Figures S3–S4 · Original trajectories with interactive landmark highlights')}`},
{id:'order',title:'Does order change prediction?',tag:'Order sensitivity',notes:"Within each 6-hour window, event content and timestamp slots are retained while events are reassigned to positions. The experiment changes event–time assignments and measures sensitivity using the mean absolute logit difference.\nSelect a heatmap cell to inspect its median and contributing-window count. During 0–6 hours, median sensitivity increases from 0.25 for windows with 3–4 events to 0.48 for windows with at least 33 events. The pattern is not strictly monotonic in every later time stratum.\nDistinguish within-window permutations, which perturb fine-grained ordering, from within-timestamp permutations, which address unresolved ordering among simultaneous records. The latter has a median sensitivity of 0.032 in Table S9.\nOpen Individual example to view the complete 0–6-hour window. The first coded PO-AKI diagnosis occurs at 5.8 hours and is marked in the figure. The same 46 events and timestamp slots are retained, with event identities assigned in reverse order. End-of-window probabilities are 1.00 in the original order and 0.02 in the reversed order; the absolute logit change is 10.12. This example illustrates how order perturbation changes the model's trajectory.",html:head('13 / WITHIN-WINDOW ORDER','The same events can lead to different predictions.','Explore population-level sensitivity and an individual 0–6 h reversal example using the same events and timestamp positions.')+`<div class="selectrow" aria-label="Order sensitivity views"><button class="active" aria-pressed="true" data-order-view="population">Population sensitivity</button><button aria-pressed="false" data-order-view="individual">Individual example · 0–6 h</button></div><div id="orderPopulation"><div class="split wide"><div><div id="heatmap" class="heatmap"></div><div class="legend"><span>Median absolute change in end-of-window logit</span><span>n = contributing windows</span></div></div><div class="stack"><div id="heatDetail"></div><div class="note-box">Windows with ≥33 events show median sensitivities of 0.40–0.50 across time strata. The relationship is not strictly monotonic in every stratum.</div><p class="small">Up to 20 permutations per window. Sensitivity measures model dependence on ordering; it does not by itself establish better predictive accuracy.</p></div></div></div><div id="orderIndividual" class="reversal-layout" hidden><div class="reversal-figure"><svg viewBox="1135 42 910 980" role="img" aria-label="Figure 6b: original and reversed event-order trajectories during the first 6 hours, with coded AKI at 5.8 hours"><defs><clipPath id="reversalCrop"><rect x="1135" y="42" width="910" height="980"/></clipPath></defs><image href="assets/figure6.png" x="0" y="0" width="2048" height="1033" clip-path="url(#reversalCrop)"/></svg></div><aside class="stack"><span class="eyebrow">ONE EPISODE · 46 EVENTS</span><h3>Same events.<br>Different arrival order.</h3><div class="risk-table"><div>Displayed window <b>0–6 h</b></div><div>First coded PO-AKI <b>5.8 h</b></div></div><div class="reversal-scores"><div><span>Original order · at 6 h</span><b>1.00</b></div><div><span>Reversed order · at 6 h</span><b>0.02</b></div></div><div class="note-box"><b>|Δlogit| at 6 h = 10.12</b><br>The same clinical events and timestamp positions were retained; event identities were assigned in reverse temporal order.</div><p class="small">The full first 6 hours are shown, including the coded PO-AKI marker at 5.8 h. The lower panel shows event counts per 0.25 h.</p></aside></div><div class="actions"><button data-figure="figure6">Original heatmap and reversal example ↗</button><button data-table="Supplementary Table S9">Within-timestamp robustness ↗</button></div>${source('Main manuscript · Figure 6a–b; Supplementary Table S9')}`},
{id:'complementary',title:'Connect temporal scales',tag:'Additional interpretation',notes:"Place the perturbation results in clinical context. Age: when other inputs are held fixed, surgery-index estimates increase monotonically with substituted age. This is consistent with the greater susceptibility of older patients to PO-AKI, but the curve is not an individual patient's natural aging trajectory. The latest original figure uses age 48 as the reference.\nProcedure: exploratory laparotomy and large-intestine resection occupy the higher substitution-logit and observed-incidence region, whereas knee arthroscopy and rotator-cuff repair occupy the lower region. The ranking may reflect procedural burden, indications, and patient selection. Across 75 procedures, a Spearman correlation of 0.667 supports empirical concordance, not a treatment effect of substituting one surgery for another.\nGrouped deletion: diabetes with complications, other kidney and ureter diseases, respiratory failure, and shock show positive model reliance across temporal windows, suggesting use of both comorbidity and acute-illness context. Kidney disease is particularly prominent in the 48 hours before surgery. Acute myocardial infarction shows a negative attribution in the figure; this requires a conditional interpretation and does not imply renal protection. Code timing, co-occurring events, and coding practices need further examination.\nAmong overlapping replicated codes, event-arrival and grouped-deletion attribution have a Spearman correlation of 0.822 and 91.9% directional agreement. This connects immediate risk updates with reliance over broader temporal windows. The comparison applies only to overlapping codes that passed both analyses' replication criteria.",html:head('14 / COMPLEMENTARY INTERPRETATION','Place model reliance in its clinical context.','Age, procedure identity and repeated clinical records offer complementary views of the information used by STREAM.')+`<div class="attribution-layout complementary-layout"><div>${fig('s2')}<div class="concordance-strip"><span><b>ρ = 0.822</b> Arrival ↔ grouped deletion</span><span><b>91.9%</b> Directional agreement</span></div><p class="small" style="margin-top:9px">Among overlapping replicated codes.</p></div><aside class="clinical-panel"><span class="eyebrow">CLINICAL READING OF FIGURE S2</span><div class="selectrow clinical-tabs" aria-label="Complementary interpretation themes"><button class="active" aria-pressed="true" data-complementary="age">Age</button><button aria-pressed="false" data-complementary="procedure">Procedure</button><button aria-pressed="false" data-complementary="history">Clinical history</button><button aria-pressed="false" data-complementary="agreement">Agreement</button></div><div id="complementaryInterpretation" aria-live="polite"></div><button class="grouped-method-btn" data-figure="s1">How grouped deletion works ↗</button><p class="small clinical-scope">Perturbation estimates characterize model reliance under the observed clinical context.</p></aside></div>${source('Main manuscript · Complementary Attribution; Supplementary Figures S1–S2')}`},
{id:'meaning',title:'Scope and next steps',tag:'Interpretation',notes:"Retain the study's main boundaries: a single-system retrospective design, a coded rather than KDIGO-defined outcome, no competing-event modeling of death, sparse positive episodes late in follow-up, and differences between recorded and clinical event times.\nPredictive accuracy does not establish clinical benefit. A threshold of 0.5 is not a validated alert threshold. External validation, calibration, workflow evaluation, and assessment of false-alert burden are needed.\nThe digital-twin implication is a potential future risk-estimation component. This study does not provide a generative patient simulator or validate treatment counterfactuals. Standardized vocabularies support future cross-system adaptation, but transferability has not yet been established.",html:head('15 / INTERPRETATION','A foundation for dynamic risk estimation, with clear limits.','The study supports an event-stream representation for this task. Clinical deployment and cross-system transfer remain future evaluations.')+`<div class="limits"><article><span class="number">GENERALIZATION</span><h3>One health system</h3><p>Retrospective temporal validation supports within-system evaluation. External institutions and new clinical domains remain untested.</p></article><article><span class="number">OUTCOME</span><h3>Documented coded AKI</h3><p>Diagnosis codes may undercapture physiologic KDIGO-defined injury. Death was not modeled as a competing event.</p></article><article><span class="number">TIME AND OBSERVATION</span><h3>Clinical records are imperfect clocks</h3><p>Tied timestamps and changing observation density affect interpretation. Later intervals have fewer positive episodes.</p></article><article><span class="number">CLINICAL USE</span><h3>Prospective utility is still open</h3><p>Alert thresholds, false-alert burden, workflow integration, recalibration and decision impact require evaluation.</p></article></div><div class="note-box" style="margin-top:20px"><b>Potential digital-twin contribution:</b> an event-updated, interpretable risk-estimation component for future perioperative digital twins. Patient simulation and treatment-effect prediction were not evaluated.</div>${source('Main manuscript · Abstract, Discussion and Limitations')}`},
{id:'takeaways',title:'What this study adds',tag:'Takeaways',notes:"Close with three points: preserve event-level structure, evaluate both surgery-index and postoperative prediction, and examine how information and event ordering change model output.\nWithin this single-system coded PO-AKI task, STREAM's predictive performance and interpretability analyses support further investigation of event-stream modeling. Cross-institutional and prospective validation remain necessary.\nAuthor order, degrees, and affiliations follow the latest manuscript title page. Xiaomeng Wang has two affiliations; Xiaoyang Ruan and Hongfang Liu are corresponding authors.",html:`<div class="conclusion-layout"><div class="conclusion-top"><div class="closing"><span class="eyebrow">STREAM / THE TAKEAWAY</span><h2>Preserve the event.<br>Update the estimate.<br>Examine the sequence.</h2><p>Longitudinal clinical context supports dynamic, interpretable prediction of coded PO-AKI.</p><button class="primary" data-go="17">Explore the evidence →</button></div><div class="conclusion-results"><div><b>0.771</b><span>Surgery-index AUPRC</span></div><div><b>0.589</b><span>Dynamic macro-AUPRC</span></div><div><b>Event-level</b><span>Interpretation over time</span></div></div></div><div class="author-panel"><span class="eyebrow">AUTHORS & AFFILIATIONS</span><p class="author-byline"><span class="author-name">Shuyu Lu MS<sup>1</sup></span>, <span class="author-name">Xiaoyang Ruan PhD<sup>2,*</sup></span>, <span class="author-name">Liwei Wang MD, PhD<sup>2</sup></span>, <span class="author-name">Jaerong Ahn PhD<sup>2</sup></span>, <span class="author-name">Andrew Wen MS<sup>2</sup></span>, <span class="author-name">Jun Jiang PhD<sup>2</sup></span>, <span class="author-name">Xiaomeng Wang MS<sup>1,2</sup></span>, <span class="author-name">Yafen Liang MD, PhD<sup>3</sup></span>, <span class="author-name">Hongfang Liu PhD<sup>2,*</sup></span></p><div class="institution-key"><p><b>1</b> McWilliams School of Biomedical Informatics, The University of Texas Health Science Center at Houston</p><p><b>2</b> Department of Quantitative and Systems Health Sciences, Dell Medical School, The University of Texas at Austin</p><p><b>3</b> Department of Anesthesiology, Critical Care and Pain Medicine, McGovern Medical School, The University of Texas Health Science Center at Houston</p><p><b>*</b> Corresponding authors</p></div></div></div>${source('Main manuscript · Author information, Abstract and Tables 2–3')}`},
{id:'library',title:'Evidence library',tag:'Appendix',notes:"This chapter brings together 13 tables, including the unified pseudocode, 10 figures, and 35 references extracted from the latest main manuscript and supplementary material. Table wording is retained. Some tables use percentages and others use the 0–1 scale; follow each table's notation.\nRedrawn presentation graphics use the original tabulated values or are explicitly labeled conceptual. Original figures can be enlarged. This public presentation package does not include Word manuscript downloads.\nBefore submission, reconcile the 2,368 baseline-positive episodes in Table S6 with the 2,371 in Table 1, review remaining uses of preoperative versus pre-index terminology, and check the correspondence between the Figure S3 bar geometry and its caption.",html:head('APPENDIX / EVIDENCE LIBRARY','The full evidence is one click away.','Original figures, complete tables, model pseudocode and manuscript references.')+`<div class="selectrow" id="libraryTabs"><button class="active" data-library="tables">Tables & algorithm</button><button data-library="figures">All 10 figures</button><button data-library="references">References</button></div><div id="libraryTableControls" class="library-controls"><label class="sr-only" for="tableSelect">Choose a table</label><select id="tableSelect"></select><label class="sr-only" for="tableSearch">Filter table rows</label><input id="tableSearch" placeholder="Filter rows…" type="search"></div><div id="libraryContent" class="library-content"></div><div class="actions"><a class="document-link" href="https://github.com/Frank-LSY/STREAM-PO-AKI" target="_blank" rel="noopener">Study code ↗</a><button class="print-btn" id="printBtn">Print presentation</button></div>${source('Source: the two manuscript files supplied for this presentation · Tables and references retain source wording')}`}
];
$('#main').innerHTML=slides.map((s,i)=>`<section class="slide" data-id="${s.id}" aria-label="Chapter ${i+1}: ${s.title}" tabindex="-1">${s.html}</section>`).join('');
let current=0,reading=false,observer;const total=slides.length;
function go(i,push=true){current=Math.max(0,Math.min(total-1,i));$$('.slide').forEach((el,k)=>el.classList.toggle('active',k===current));$('#counter').textContent=`${String(current+1).padStart(2,'0')} / ${total}`;$('#sectionLabel').textContent=slides[current].tag+' / '+slides[current].title;$('#progress').style.width=((current+1)/total*100)+'%';$('#prevBtn').disabled=current===0;$('#nextBtn').disabled=current===total-1;$('#notesText').innerHTML=slides[current].notes.split('\n').map(x=>`<p>${x}</p>`).join('');if(push)history.replaceState(null,'','#'+(current+1));if(reading){document.querySelectorAll('.slide')[current].scrollIntoView({behavior:'smooth',block:'start'});}else window.scrollTo(0,0);}
$('#prevBtn').onclick=()=>go(current-1);$('#nextBtn').onclick=()=>go(current+1);
function openOverview(){ $('#chapterGrid').innerHTML=slides.map((s,i)=>`<button data-chapter="${i}" class="${i===current?'active':''}"><span>${String(i+1).padStart(2,'0')} / ${s.tag.toUpperCase()}</span>${s.title}</button>`).join('');$('#overview').showModal();}
$('#overviewBtn').onclick=openOverview;
function toggleNotes(){let open=$('#notes').hidden;$('#notes').hidden=!open;$('#notesBtn').setAttribute('aria-pressed',String(open));}$('#notesBtn').onclick=toggleNotes;$('#closeNotes').onclick=toggleNotes;
$('#modeBtn').onclick=()=>{reading=!reading;document.body.classList.toggle('reading',reading);$('#modeBtn').textContent=reading?'Presentation view':'Reading view';$('#modeBtn').setAttribute('aria-pressed',String(reading));go(current,false);};
$('#fullBtn').onclick=async()=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen();}catch(e){$('#fullBtn').title='Full screen is unavailable in this browser';}};
function showFigure(id){let f=figures[id];$('#evidenceTitle').textContent=f[0];$('#evidenceCaption').textContent=f[1];$('#evidenceImage').src=`assets/${id}.png`;$('#evidenceImage').alt=f[0];$('#imageLink').href=`assets/${id}.png`;$('.image-stage').classList.remove('zoomed');$('#zoomBtn').textContent='Zoom in';$('#evidence').showModal();}
$('#zoomBtn').onclick=()=>{let on=$('.image-stage').classList.toggle('zoomed');$('#zoomBtn').textContent=on?'Fit image':'Zoom in';};
document.addEventListener('click',e=>{const f=e.target.closest('[data-figure]');if(f)showFigure(f.dataset.figure);const g=e.target.closest('[data-go]');if(g)go(+g.dataset.go);const ch=e.target.closest('[data-chapter]');if(ch){$('#overview').close();go(+ch.dataset.chapter);}const cl=e.target.closest('[data-close]');if(cl)cl.closest('dialog').close();const tb=e.target.closest('[data-table]');if(tb)openTable(tb.dataset.table);});
document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||document.querySelector('dialog[open]'))return;if(['ArrowRight','PageDown'].includes(e.key)||(e.key===' '&&!e.target.closest('button,a'))){e.preventDefault();go(current+1);}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();go(current-1);}if(e.key.toLowerCase()==='g')openOverview();if(e.key.toLowerCase()==='n')toggleNotes();if(e.key==='Escape'&&!$('#notes').hidden)toggleNotes();});
window.addEventListener('hashchange',()=>go((parseInt(location.hash.slice(1))||1)-1,false));
const tokenInfo={demo:['Demographic events','Age, sex and race enter at day −7. Age includes a numerical value standardized using training-fold statistics.'],cond:['Condition events','Diagnosis codes map to CCS categories, reducing coding heterogeneity while retaining clinically meaningful groups.'],med:['Medication events','Ingredient-level RxNorm codes. Ingredients covering 90% of event frequency are retained; others map to MED_OTHERS. Start/end boundaries are encoded separately.'],lab:['Laboratory events','21 common or renal-function-related test types are retained. Values are unit-harmonized and normalized within the training fold; other tests map to LAB_OTHERS.'],surgery:['The surgery anchor','A SNOMED CT surgery token is placed at the recorded surgery completion time, t₀ = 0.'],base:['The learnable [BASE] state','Inserted immediately after surgery. It supports surgery-index prediction and carries the pre-index history into postoperative updating.'],post:['Postoperative events','Each new event produces an updated estimate. Attention is limited to [BASE] and postoperative events through the current position.']};
function setToken(key){$('#tokenDetail').innerHTML=`<h3>${tokenInfo[key][0]}</h3><p style="margin-top:13px">${tokenInfo[key][1]}</p>`;$$('[data-token]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.token===key)));}$$('[data-token]').forEach(b=>b.onclick=()=>setToken(b.dataset.token));setToken('demo');
const labels=['e₀','e₁','e₂','Surgery','[BASE]','post₁','post₂','post₃','post₄'];function visible(r,c){return r<4?c<4:r===4?c<=4:c===4||(c>=5&&c<=r);}
function drawMatrix(row=4){let h='<span></span>'+labels.map(x=>`<span class="axis">${x}</span>`).join('');for(let r=0;r<9;r++){h+=`<span class="axis rowlabel">${labels[r]}</span>`;for(let c=0;c<9;c++)h+=`<button class="${visible(r,c)?'allowed':''} ${r===row?'query':''} ${r===row&&visible(r,c)?'lit':''} ${r===4&&c===4?'basecell':''}" data-query="${r}" aria-label="Query ${labels[r]}, key ${labels[c]}: ${visible(r,c)?'visible':'masked'}" title="${labels[r]} → ${labels[c]}: ${visible(r,c)?'visible':'masked'}"></button>`;}$('#attentionMatrix').innerHTML=h;let title,text;if(row<4){title='Pre-index: bidirectional context';text='Each pre-index position can attend to every position in the pre-index segment, including the surgery token. Postoperative information is masked.';}else if(row===4){title='[BASE]: the surgery-index summary';text='The baseline query attends to all pre-index positions and itself. Its prediction summarizes the recorded information available by surgery completion.';}else{title=`Postoperative query ${row-4}: history without future events`;text='This position can attend to [BASE], itself and prior postoperative positions. Later postoperative events are masked.';}$('#attentionExplanation').innerHTML=`<span class="number">SELECTED QUERY · ${labels[row]}</span><h3>${title}</h3><p>${text}</p>`;$$('[data-query]').forEach(b=>b.onclick=()=>drawMatrix(+b.dataset.query));}drawMatrix();
const perf=[{name:'Logistic Regression',basepr:.6117,baseroc:.9105},{name:'XGBoost',basepr:.6047,baseroc:.9069},{name:'LSTM',basepr:.6776,baseroc:.9242,dynpr:.4449,dynroc:.9324},{name:'GRU-D',basepr:.6948,baseroc:.9263,dynpr:.5470,dynroc:.9423},{name:'Time-series Transformer',basepr:.7288,baseroc:.9333,dynpr:.5245,dynroc:.9476},{name:'STREAM',basepr:.7714,baseroc:.9419,dynpr:.5886,dynroc:.9482}];
const metricInfo={basepr:['SURGERY-INDEX AUPRC','0.7714','+4.26 percentage points','Compared with 0.7288 for the Time-series Transformer.'],dynpr:['DYNAMIC MACRO-AUPRC','0.5886','+4.16 percentage points','Compared with 0.5470 for GRU-D, the strongest fixed-window model on this metric.'],baseroc:['SURGERY-INDEX AUROC','0.9419','Highest reported mean','Compared with 0.9333 for the Time-series Transformer.'],dynroc:['DYNAMIC MACRO-AUROC','0.9482','Closely matched AUROC','Time-series Transformer: 0.9476. The larger separation appears in macro-AUPRC.']};
function metric(key){$('#performanceBars').innerHTML=perf.map(m=>`<div class="metricbar ${m.name==='STREAM'?'highlight':''}"><span>${m.name}</span><div class="track"><div class="fill" style="width:${(m[key]||0)*100}%"></div></div><strong class="${m[key]===undefined?'na':''}">${m[key]===undefined?'—':m[key].toFixed(4)}</strong></div>`).join('');let m=metricInfo[key];$('#metricSummary').innerHTML=`<span class="eyebrow">${m[0]}</span><span class="big">${m[1]}</span><h3 style="font-size:21px;margin-top:23px">${m[2]}</h3><p>${m[3]}</p><small style="margin-top:25px">Means across five fold-specific models.<br>No significance claim is inferred from these differences.</small>`;$$('[data-metric]').forEach(b=>b.classList.toggle('active',b.dataset.metric===key));}$$('[data-metric]').forEach(b=>b.onclick=()=>metric(b.dataset.metric));metric('basepr');
