function calibration(i){let d=cal[i];$('#brierGrid').innerHTML=['LSTM','GRU-D','Time-series Transformer','STREAM'].map((name,k)=>`<div class="brier-item ${k===3?'main':''}"><span>${name}</span><b>${d.b[k].toFixed(3)}</b><small>Brier score · lower is better<br>Skill score ${d.s[k].toFixed(3)}</small></div>`).join('');$('#calDetail').innerHTML=`<div class="risk-table"><div>Episodes still at risk <b>${d.n.toLocaleString()}</b></div><div>Subsequent coded PO-AKI <b>${d.pos.toLocaleString()} (${(d.pos/d.n*100).toFixed(1)}%)</b></div><div>STREAM calibration intercept <b>${d.int.toFixed(2)}</b></div><div>STREAM calibration slope <b>${d.slope.toFixed(2)}</b></div></div>`;$$('[data-cal]').forEach(b=>b.classList.toggle('active',+b.dataset.cal===i));}$$('[data-cal]').forEach(b=>b.onclick=()=>calibration(+b.dataset.cal));calibration(1);
