function clinicalTheme(key){const d=clinicalThemes[key];$('#clinicalInterpretation').innerHTML=`<div class="clinical-direction ${key==='casemix'?'decrease':'increase'}">${d.direction}</div><h3>${d.title}</h3><ul class="clinical-codes">${d.codes.map(x=>'<li>'+x+'</li>').join('')}</ul><p>${d.text}</p><p class="clinical-reference">${d.foot}</p>`;$$('[data-clinical]').forEach(b=>{b.classList.toggle('active',b.dataset.clinical===key);b.setAttribute('aria-pressed',String(b.dataset.clinical===key));});}
$$('[data-clinical]').forEach(b=>b.onclick=()=>clinicalTheme(b.dataset.clinical));clinicalTheme('vulnerability');
const complementaryThemes={
age:{label:'AGE SUBSTITUTION · 20–90 YEARS',title:'A clinically coherent age gradient',finding:'With other inputs held fixed, surgery-index risk increases monotonically with substituted age, relative to age 48.',reading:'The direction agrees with older age as an established PO-AKI risk factor. This probes the age information learned by STREAM; it is not a longitudinal aging trajectory for an individual patient.',foot:'Clinical context: <a href="https://www.nature.com/articles/s41581-021-00418-2" target="_blank" rel="noopener">ADQI / POQI consensus ↗</a>'},
procedure:{label:'PROCEDURE SUBSTITUTION · 75 TYPES',title:'Procedure identity carries clinical context',finding:'Exploratory laparotomy and large intestine excision occupy the higher-logit, higher-incidence region; knee arthroscopy and rotator cuff repair lie toward the lower end.',reading:'The ranking may encode operative burden, indication and patient selection. Its correlation with observed incidence (ρ = 0.667) supports empirical consistency, without estimating what changing an actual patient’s operation would do.',foot:'Reference: minimally invasive decompression of lumbar spine, as shown in Figure S2.'},
history:{label:'TEMPORAL GROUPED DELETION',title:'Comorbidity and acute illness across time',finding:'Diabetes with complications, kidney / ureter disease, respiratory failure and shock show positive contributions across multiple perioperative windows. Kidney / ureter disease is especially prominent in the final 48 h before surgery.',reading:'These patterns suggest reliance on both background disease and evolving illness. The negative acute-myocardial-infarction attribution illustrates that code effects are context-dependent; it should not be interpreted as renal protection.',foot:'Window-specific contributions can reflect timing, co-recorded conditions and coding practices.'},
agreement:{label:'TWO TEMPORAL SCALES',title:'Related signals at arrival and over time',finding:'Among overlapping replicated codes, the two analyses show Spearman ρ = 0.822 and 91.9% directional agreement.',reading:'A clinical signal that changes risk when it arrives often also contributes when its repeated records are examined over a broader period. This supports a consistent interpretation of model reliance at the two temporal scales.',foot:'Agreement concerns the shared selected codes; it does not establish a causal clinical mechanism.'}
};
function complementaryTheme(key){const d=complementaryThemes[key];$('#complementaryInterpretation').innerHTML=`<span class="clinical-direction">${d.label}</span><h3>${d.title}</h3><p class="complementary-finding"><b>Observed pattern</b>${d.finding}</p><p class="complementary-reading"><b>Clinical interpretation</b>${d.reading}</p><p class="clinical-reference">${d.foot}</p>`;$$('[data-complementary]').forEach(b=>{b.classList.toggle('active',b.dataset.complementary===key);b.setAttribute('aria-pressed',String(b.dataset.complementary===key));});}
$$('[data-complementary]').forEach(b=>b.onclick=()=>complementaryTheme(b.dataset.complementary));complementaryTheme('age');
