function drawPatient(){const p=caseData[patient],d=p[caseModel];caseStep=Math.min(caseStep,d.steps.length-1);const st=d.steps[caseStep];const w=caseModel==='s3'?1853:2015,h=caseModel==='s3'?2048:891;$('#patientFigure').innerHTML=`<svg viewBox="${d.box}" role="img" aria-label="${caseModel==='s3'?'STREAM':'Time-series Transformer'} trajectory for ${p.title}; ${st[1]}"><defs><clipPath id="patientCrop"><rect x="${d.box.split(' ')[0]}" y="${d.box.split(' ')[1]}" width="${d.box.split(' ')[2]}" height="${d.box.split(' ')[3]}"/></clipPath></defs><image href="assets/${caseModel}.png" width="${w}" height="${h}" clip-path="url(#patientCrop)"/>${st[3]===null?'':`<rect class="landmark-highlight" x="${st[3]-st[4]/2}" y="${d.y}" width="${st[4]}" height="${d.h}" fill="#e8b55a" fill-opacity=".13" stroke="#a07324" stroke-width="2" stroke-dasharray="8 6"/>`}</svg>`;
$('#patientBadge').textContent=(patient==='positive'?'CODED PO-AKI':'NO CODED PO-AKI')+' · '+(caseModel==='s3'?'STREAM':'TIME-SERIES TRANSFORMER');$('#patientTitle').textContent=p.title;$('#patientOutcome').textContent=p.outcome;$('#landmarkInfo').innerHTML=`<span class="number">${st[0]}</span><h3>${st[1]}</h3><p>${st[2]}</p>`;$('#patientLegend').textContent=caseModel==='s3'?'Red / blue: increased / decreased model-estimated risk. Darker bars mark threshold-crossing updates. Dashed line: probability trajectory.':'The prediction updates at predefined 6-hour intervals. The dashed horizontal line marks the 0.50 reference threshold.';
$('#caseLandmarks').innerHTML=d.steps.map((v,i)=>`<button data-landmark="${i}" class="${i===caseStep?'active':''}" aria-pressed="${i===caseStep}">${v[0]}</button>`).join('');$('#casePosition').textContent=`${caseStep+1} / ${d.steps.length}`;$('#casePrev').disabled=caseStep===0;$('#caseNext').disabled=caseStep===d.steps.length-1;$$('[data-landmark]').forEach(b=>b.onclick=()=>{caseStep=+b.dataset.landmark;drawPatient();});$$('[data-patient]').forEach(b=>{b.classList.toggle('active',b.dataset.patient===patient);b.setAttribute('aria-pressed',String(b.dataset.patient===patient));});$$('[data-case]').forEach(b=>{b.classList.toggle('active',b.dataset.case===caseModel);b.setAttribute('aria-pressed',String(b.dataset.case===caseModel));});}
$$('[data-patient]').forEach(b=>b.onclick=()=>{patient=b.dataset.patient;caseStep=0;drawPatient();});$$('[data-case]').forEach(b=>b.onclick=()=>{caseModel=b.dataset.case;caseStep=0;drawPatient();});$('#casePrev').onclick=()=>{caseStep--;drawPatient();};$('#caseNext').onclick=()=>{caseStep++;drawPatient();};$('#caseOriginal').onclick=()=>showFigure(caseModel);drawPatient();
