const heatValues=[[.25,.27,.34,.46,.48],[.22,.26,.27,.30,.40],[.21,.23,.24,.23,.50],[.20,.23,.28,.26,.41]],heatCounts=[[1087,1032,1468,2546,1614],[1226,1376,954,646,862],[1337,1479,951,470,406],[1647,2673,2355,774,502]],periods=['0–6 h','6–24 h','24–72 h','72 h–7 d'],densities=['3–4','5–8','9–16','17–32','≥33'];
function heat(r=0,c=4){let out='<span class="label">Postoperative<br>period</span>'+densities.map(x=>`<span class="label">${x} events</span>`).join('');for(let i=0;i<4;i++){out+=`<span class="label">${periods[i]}</span>`;for(let j=0;j<5;j++){let v=heatValues[i][j],k=(v-.2)/.3;out+=`<button data-hrow="${i}" data-hcol="${j}" class="${i===r&&j===c?'selected':''}" style="background:hsl(${46-k*35} 80% ${88-k*42}%)" aria-label="${periods[i]}, ${densities[j]} events, median ${v.toFixed(2)}, ${heatCounts[i][j]} windows"><b>${v.toFixed(2)}</b><span>n = ${heatCounts[i][j].toLocaleString()}</span></button>`;}}$('#heatmap').innerHTML=out;$('#heatDetail').innerHTML=`<span class="eyebrow">${periods[r]} · ${densities[c]} EVENTS / WINDOW</span><div class="large-number">${heatValues[r][c].toFixed(2)}</div><p class="small" style="margin-top:12px">Median |Δlogit| across ${heatCounts[r][c].toLocaleString()} contributing windows.</p>`;$$('[data-hrow]').forEach(b=>b.onclick=()=>heat(+b.dataset.hrow,+b.dataset.hcol));}heat();
let evidenceData=null,libraryMode='tables';const escapeHtml=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function library(mode='tables'){libraryMode=mode;$$('[data-library]').forEach(b=>b.classList.toggle('active',b.dataset.library===mode));$('#libraryTableControls').hidden=mode!=='tables';if(!evidenceData){$('#libraryContent').textContent='Loading source evidence…';return;}if(mode==='figures'){$('#libraryContent').innerHTML=`<div class="figure-grid">${Object.entries(figures).map(([id,f])=>`<button data-figure="${id}"><img src="assets/${id}.png" alt="${f[0]}" loading="lazy"><span>${f[0]}</span></button>`).join('')}</div>`;}else if(mode==='references'){$('#libraryContent').innerHTML='<ol class="refs">'+evidenceData.references.map(x=>'<li>'+escapeHtml(x.replace(/^\d+\.\s*/,''))+'</li>').join('')+'</ol>';}else renderTable();}
function renderTable(){if(!evidenceData)return;let t=evidenceData.tables[+$('#tableSelect').value||0],filter=$('#tableSearch').value.toLowerCase(),rows=t.rows.map((r,i)=>({r,i})).filter(({r,i})=>!filter||i===0||r.join(' ').toLowerCase().includes(filter));$('#libraryContent').innerHTML=`<div class="table-wrap"><table><caption style="text-align:left;padding:15px;font-weight:700">${escapeHtml(t.title)}</caption><tbody>${rows.map(({r,i})=>'<tr>'+r.map((x,j)=>`<${i===0?'th':'td'} colspan="${t.spans?.[i]?.[j]||1}">${escapeHtml(x)}</${i===0?'th':'td'}>`).join('')+'</tr>').join('')}</tbody></table></div>`;}
function openTable(title){go(total-1);libraryMode='tables';$('#tableSearch').value='';if(evidenceData){let i=evidenceData.tables.findIndex(t=>t.title.includes(title));$('#tableSelect').value=String(Math.max(0,i));}library('tables');}
$$('[data-library]').forEach(b=>b.onclick=()=>library(b.dataset.library));$('#tableSelect').onchange=renderTable;$('#tableSearch').oninput=renderTable;$('#printBtn').onclick=()=>window.print();
